  Lemma aclient_range_sub : forall LB SP A n A' n',
    aclient_range HI LB SP A n -> A <= A' -> A' + n' <= A + n -> 0 <= n' -> aclient_range HI LB SP A' n'.
  Proof.
    intros LB SP A n A' n' HR H1 H2 H3. unfold aclient_range in *.
    destruct HR as [K|[K|[(b & Hb & K1 & K2)|[(b & Hb & K1 & K2)|[K|[K|K]]]]]].
    - left. lia.
    - right; left. intros a Ha. apply K. lia.
    - right; right; left. exists b. split; [exact Hb| lia].
    - right; right; right; left. exists b. split; [exact Hb| lia].
    - right; right; right; right; left. lia.
    - right; right; right; right; right; left. lia.
    - right; right; right; right; right; right. lia.
  Qed.

  Lemma aclient_range_SP_mono : forall LB SP SP' A n, aclient_range HI LB SP A n -> SP' <= SP -> aclient_range HI LB SP' A n.
  Proof.
    intros LB SP SP' A n HR HS. unfold aclient_range in *.
    destruct HR as [K|K]; [left; lia| right; exact K].
  Qed.

  Lemma aclient_range_LB_mono : forall LB LB' SP A n,
    aclient_range HI LB SP A n -> (forall b, In b LB -> In b LB') -> aclient_range HI LB' SP A n.
  Proof.
    intros LB LB' SP A n HR HL. unfold aclient_range in *.
    destruct HR as [K|[K|[(b & Hb & K1 & K2)|[(b & Hb & K1 & K2)|K]]]]; [left; exact K| right; left; exact K| | | right; right; right; right; exact K].
    - right; right; left. exists b. split; [apply HL; exact Hb| lia].
    - right; right; right; left. exists b. split; [apply HL; exact Hb| lia].
  Qed.

  Lemma aclient_write_ok_cons : forall LB b iv, aclient_write_ok HI LB iv -> aclient_write_ok HI (b :: LB) iv.
  Proof.
    intros LB b iv HW. unfold aclient_write_ok in *.
    destruct HW as [K|[K|[(b' & Hb & K1 & K2)|[(b' & Hb & K1 & K2)|K]]]]; [left; exact K| right; left; exact K| | | right; right; right; right; exact K].
    - right; right; left. exists b'. split; [right; exact Hb| split; assumption].
    - right; right; right; left. exists b'. split; [right; exact Hb| split; assumption].
  Qed.

  Lemma aclient_addr_range : forall LB SP a, aclient_addr HI LB SP a -> aclient_range HI LB SP a 1.
  Proof.
    intros LB SP a Hc. unfold aclient_addr, aclient_range in *.
    destruct Hc as [K|[K|[(b & Hb & K)|[(b & Hb & K)|[K|[K|K]]]]]]; [left; lia| right; left; intros x Hx; replace x with a by lia; exact K| | | right; right; right; right; left; lia| right; right; right; right; right; left; lia| right; right; right; right; right; right; lia].
    - right; right; left. exists b. split; [exact Hb| lia].
    - right; right; right; left. exists b. split; [exact Hb| lia].
  Qed.
