  Definition aobj (LB : list block) (LF : list fframe) (A n : Z) : Prop :=
    (exists b, In b LB /\ blk_addr b <= A /\ A + n <= blk_addr b + blk_size b)
    \/ (exists f, In f LF /\ ff_addr f <= A /\ A + n <= ff_addr f + fsz (ff_class f)).

  Lemma aobj_block : forall LB LF p A n a k, In (p, A, n) LB -> A <= a -> a + k <= A + n -> aobj LB LF a k.
  Proof. intros LB LF p A n a k IN H1 H2. left. exists (p, A, n). split; [exact IN| cbn; lia]. Qed.

  Lemma aobj_frame : forall LB LF f a k, In f LF -> ff_addr f <= a -> a + k <= ff_addr f + fsz (ff_class f) -> aobj LB LF a k.
  Proof. intros LB LF f a k IN H1 H2. right. exists f. auto. Qed.

  Lemma aobj_sub : forall LB LF A n A' n', aobj LB LF A n -> A <= A' -> A' + n' <= A + n -> aobj LB LF A' n'.
  Proof.
    intros LB LF A n A' n' [(b & Hb & H1 & H2)|(f & Hf & H1 & H2)] L1 L2; [left; exists b| right; exists f]; split; [assumption| lia| assumption| lia].
  Qed.

  Lemma aobj_LB_mono : forall LB LB' LF A n, aobj LB LF A n -> (forall b, In b LB -> In b LB') -> aobj LB' LF A n.
  Proof.
    intros LB LB' LF A n [(b & Hb & H1 & H2)|K] HL; [left| right; exact K]. exists b. split; [apply HL; exact Hb| lia].
  Qed.

  Lemma aobj_LF_mono : forall LB LF LF' A n, aobj LB LF A n -> (forall f, In f LF -> In f LF') -> aobj LB LF' A n.
  Proof.
    intros LB LF LF' A n [K|(f & Hf & H1 & H2)] HL; [left; exact K| right]. exists f. split; [apply HL; exact Hf| lia].
  Qed.

