  Lemma aobj_in_app : forall s LB m LF m1 A n,
    as_RHEAP H s LB m -> as_RFS H LF m1 -> aobj LB LF A n -> 0 <= n -> in_app_mem A (A + n).
  Proof.
    intros s LB m LF m1 A n RH RF AO Hn. eapply aapp_in_app_mem; [eapply aobj_aapp; [exact RH| exact RF| exact AO] | lia| lia].
  Qed.

  (* [comment removed for export] *)
  Lemma aobj_after_free : forall s LB m p Ap np s2 m2 p' A' n' LF A n,
    as_RHEAP H s LB m -> In (p, Ap, np) LB -> as_RHEAP H s2 ((p', A', n') :: LB) m2 ->
    aobj LB LF A n -> (A + n <= Ap \/ Ap + np <= A) -> 0 < n ->
    aobj (as_lb_remove H p ((p', A', n') :: LB)) LF A n.
  Proof.
    intros s LB m p Ap np s2 m2 p' A' n' LF A n RH Hin RH2 AO DJ Hn.
    rewrite (ah_lb_remove_fresh H HH _ _ _ _ _ _ _ RH2) by (apply in_map_iff; exists (p, Ap, np); split; [reflexivity| exact Hin]).
    destruct AO as [(b & Hb & H1 & H2)|K]; [left| right; exact K]. exists b. split; [| split; assumption]. right.
    apply (ah_lb_remove_keep H HH); [exact (ah_nodup H HH _ _ _ RH)| exact Hb|].
    intros E. assert (b = (p, Ap, np)) by (eapply nodup_blk_eq; [exact (ah_nodup H HH _ _ _ RH)| exact Hb| exact Hin| exact E]).
    subst b. cbn in H1, H2. pose proof (ah_blocks H HH _ _ _ _ RH Hin) as (_ & _ & R3 & _). cbn in R3. lia.
  Qed.

  (* [comment removed for export] *)
  Lemma fresh_block_outside_aobj : forall s LB m LF m1 s' m' p A n a k,
    as_RHEAP H s LB m -> as_RFS H LF m1 -> as_RHEAP H s' ((p, A, n) :: LB) m' -> aobj LB LF a k -> 0 < k ->
    a + k <= A \/ A + n <= a.
  Proof.
    intros s LB m LF m1 s' m' p A n a k RH RF RH' AO Hk.
    eapply (fresh_block_disjoint_client H HH) with (SP := aceil); [exact RH'| eapply aobj_client; [exact RH| exact RF| exact AO] | lia| exact Hk].
  Qed.

  (* [comment removed for export] *)
  Lemma aobj_off_frame : forall s LB m LF m1 A n lo SP,
    as_RHEAP H s LB m -> as_RFS H LF m1 -> aobj LB LF A n -> aceil <= lo -> A + n <= lo \/ SP <= A.
  Proof. intros s LB m LF m1 A n lo SP RH RF AO CE. left. pose proof (aobj_range _ _ _ _ _ _ _ RH RF AO). lia. Qed.

  Lemma aobj_chain_nil : forall s LB m LF m1 A n m2,
    as_RHEAP H s LB m -> as_RFS H LF m1 -> aobj LB LF A n -> 0 < n -> as_chain H m2 A [].
  Proof. intros s LB m LF m1 A n m2 RH RF AO Hn. apply (ah_chain_nil H HH). left. pose proof (aobj_range _ _ _ _ _ _ _ RH RF AO). lia. Qed.

  (* [comment removed for export] *)
  Lemma aobj_apres_accessible : forall s LB m0 LF m1 SP m m' A n a k,
    as_RHEAP H s LB m0 -> as_RFS H LF m1 -> aobj LB LF A n -> apres H LB SP m m' ->
    accessible m a k -> A <= a -> a + k <= A + n -> accessible m' a k.
  Proof.
    intros s LB m0 LF m1 SP m m' A n a k RH RF AO AP AC H1 H2. eapply apres_accessible; [exact AP| exact AC|].
    intros x Hx. eapply aobj_shclient; [exact RH| exact RF| exact AO| lia].
  Qed.

