  induction X as [|[l h] X IH]; intros a FA; cbn; [tauto|].
  pose proof (Forall_inv FA) as K1. cbn in K1. pose proof (IH a (Forall_inv_tail FA)) as K2. intros [K|K]; [lia| exact (K2 K)].
Qed.

Lemma rin_ivs_mono_app : forall X Y a, rin_ivs X a -> rin_ivs (X ++ Y) a.
Proof. intros X Y a K. rewrite rin_ivs_app. left. exact K. Qed.

Lemma rin_ivs_In : forall X l hh a, In (l, hh) X -> l <= a < hh -> rin_ivs X a.
Proof. induction X as [|iv X IH]; intros l hh a IN Ha; [destruct IN|]. cbn. destruct IN as [->|IN]; [left; cbn; exact Ha| right; eapply IH; eauto]. Qed.

