Lemma lb_bytes_app : forall l1 l2, lb_bytes (l1 ++ l2) = lb_bytes l1 + lb_bytes l2.
Proof. induction l1 as [|b l1 IH]; intros l2; [reflexivity|]. cbn [app]. rewrite !lb_bytes_cons, IH. lia. Qed.

Lemma nodup_map_inj : forall (l : list block) x y, List.NoDup (map blk_id l) -> In x l -> In y l -> blk_id x = blk_id y -> x = y.
Proof.
  induction l as [|c l IH]; intros x y ND Hx Hy E; [destruct Hx|].
  cbn in ND. inversion ND as [|z l' NI ND']; subst.
  destruct Hx as [<-|Hx]; destruct Hy as [<-|Hy]; [reflexivity| | | apply IH; assumption].
  - exfalso. apply NI. rewrite E. apply in_map. exact Hy.
  - exfalso. apply NI. rewrite <- E. apply in_map. exact Hx.
Qed.

