  Lemma scratch_Forall : forall LF m LB XS, as_RFS H LF m -> Forall (fs_scratch H LF) XS ->
    Forall (aclient_write_ok H LB) XS /\ (forall a n, a + n <= AIMG_TOP -> disjoint_from XS a n) /\ (forall a n, aceil <= a -> disjoint_from XS a n).
  Proof.
    intros LF m LB XS RF FX. all: aapp_facts. induction XS as [|iv XS IH].
    { split; [constructor|]. split; intros; exact I. }
    pose proof (scratch_facts LF m LB iv RF (Forall_inv FX)) as (A1 & A3 & A4). destruct (IH (Forall_inv_tail FX)) as (B1 & B3 & B4).
    split; [constructor; assumption|]. split.
    - intros a n Hn. destruct iv as [l h]. cbn in A3 |- *. split; [lia| apply B3; exact Hn].
    - intros a n Hn. destruct iv as [l h]. cbn in A4 |- *. split; [lia| apply B4; exact Hn].
  Qed.

  Lemma disjoint_scratch : forall LF m XS O n, as_RFS H LF m -> fsobj H LF O n -> 0 <= n -> O + n <= AAPP_HI -> aapp O n ->
    Forall (fs_scratch H LF) XS -> disjoint_from XS O n.
  Proof.
    intros LF m XS O n RF OB Hn Htop Hlo FX. all: aapp_facts. induction XS as [|[l h] XS IH]; cbn; [exact I|].
    split; [| apply IH; exact (Forall_inv_tail FX)].
    exact (fsobj_scratch H HH LF O n m (l, h) RF OB ltac:((aapp_facts; unfold AHI_LO, AIMG_TOP, ALOWSH_LO in Hlo); lia) Hn Htop Hlo (Forall_inv FX)).
  Qed.

  Lemma disjoint_scratch_sh : forall LF m XS O n, as_RFS H LF m -> fsobj H LF O n -> 0 <= n -> O + n <= AAPP_HI -> aapp O n ->
