  (* [comment removed for export] *)
  Lemma lb_remove_split : forall p A1 n LB,
    List.NoDup (map blk_id LB) -> In (p, A1, n) LB ->
    exists l1 l2, LB = l1 ++ (p, A1, n) :: l2 /\ as_lb_remove H p LB = l1 ++ l2.
  Proof.
    intros p A1 n LB. all: aapp_facts. induction LB as [|b LB IH]; intros ND IN; [destruct IN|].
    cbn in ND. inversion ND as [|x l NI ND']; subst.
    destruct IN as [EB|IN].
    - subst b. exists [], LB. split; [reflexivity|]. cbn. apply (proj1 (ah_lb_remove H HH)). exact NI.
    - destruct (IH ND' IN) as (l1 & l2 & E1 & E2).
      assert (NE : blk_id b <> p).
      { intros E. apply NI. rewrite E. change p with (blk_id (p, A1, n)). apply in_map. exact IN. }
      exists (b :: l1), l2. split; [rewrite E1; reflexivity|].
      rewrite (proj1 (proj2 (ah_lb_remove H HH))) by exact NE. rewrite E2. reflexivity.
  Qed.
End SCR.

