  Lemma AXStatics_xpres : forall LB SP X m m',
    AXStatics m -> xpres H LB SP X m m' -> Forall (fun iv : Z * Z => 0x12a180 <= fst iv \/ snd iv <= 0x119000) X -> AXStatics m'.
