    intros LB SP X m m' XS XP FX. unfold AXStatics in *.
    eapply xpres_rw_cells; [exact XP| exact XS|]. apply xclient_range_img.
    - intros a Ha. unfold aimg_client. revert Ha. unfold AVP_HTTP_ECAT. cbn. lia.
    - eapply Forall_impl; [| exact FX]. intros [lo hi] K; unfold AVP_HTTP_ECAT; cbn in *. lia.
  Qed.
