  Lemma AFlatBuf_transport_awin : forall W LB m m' a F ds,
    AFlatBuf LB m a F ds -> munch W m m' -> wmono bsegs m m' -> Forall awin W -> disjoint_from W a SZ_FB ->
    (F <> FB_empty -> disjoint_from W (fb_begin F) (fb_cap F)) -> AFlatBuf LB m' a F ds.
  Proof.
    intros W LB m m' a F ds FB MU WM FW D DB. eapply AFlatBuf_transport; [exact FB| exact MU| exact WM| exact D| exact DB|].
    intros NE. destruct FB as (_ & OK & _). destruct OK as [E|(p & IN & RB & _)]; [contradiction|].
    pose proof (rblock_bounds _ _ RB) as (B1 & B2 & B3 & _). apply awin_sh_disjoint; assumption.
  Qed.

