  Lemma AStateBlock_transport_awin : forall W LB m m' b ioc implb S ds,
    AStateBlock LB m b ioc implb S ds -> munch W m m' -> wmono bsegs m m' -> Forall awin W -> disjoint_from W b SZ_SPCI_STATE ->
    (st_fb S <> FB_empty -> disjoint_from W (fb_begin (st_fb S)) (fb_cap (st_fb S))) -> AStateBlock LB m' b ioc implb S ds.
  Proof.
    intros W LB m m' b ioc implb S ds P MU WM FW D DF.
    pose proof P as (p & j7 & j16 & j4 & _ & RB & _ & _ & _ & _ & _ & _ & FB & _).
    pose proof (rblock_bounds _ _ RB) as (B1 & B2 & B3 & _).
    eapply AStateBlock_transport; [exact P| exact MU| exact WM| exact D| exact DF| apply awin_sh_disjoint; assumption|].
