  Lemma AConfigSvc_xpres : forall LB SP X m m' c S,
    AConfigSvc LB m c S -> xpres H LB SP X m m' -> Forall (fun iv : Z * Z => c + NEWSZ_CFG <= fst iv \/ snd iv <= c) X ->
    Forall (fun iv : Z * Z => sh c + nsh NEWSZ_CFG <= fst iv \/ snd iv <= sh c) X -> AConfigSvc LB m' c S.
  Proof.
    intros LB SP X m m' c S (p & j4 & j7 & IN & CH & E1 & E2 & RB & AD) XP FX FXS. exists p, j4, j7.
    pose proof (blk_xclient_range LB SP X p c NEWSZ_CFG) as XR. specialize (fun A k => XR A k IN FX).
    assert (AD' : addressable m' c NEWSZ_CFG) by (xp_addr XP AD IN FXS). clear AD FXS.
    unfold NEWSZ_CFG in *. split; [exact IN|]. split; [xp_keep XP XR|]. split; [exact E1|]. split; [exact E2|]. split; [exact RB| exact AD'].
  Qed.

  Lemma AStreamSvc_xpres : forall LB SP X m m' v S implb,
    AStreamSvc LB m v S implb -> xpres H LB SP X m m' -> Forall (fun iv : Z * Z => v + NEWSZ_SSVC <= fst iv \/ snd iv <= v) X ->
    Forall (fun iv : Z * Z => sh v + nsh NEWSZ_SSVC <= fst iv \/ snd iv <= sh v) X -> AStreamSvc LB m' v S implb.
  Proof.
    intros LB SP X m m' v S implb (p & j7 & IN & CH & E1 & E2 & RB & AD) XP FX FXS. exists p, j7.
    pose proof (blk_xclient_range LB SP X p v NEWSZ_SSVC) as XR. specialize (fun A k => XR A k IN FX).
    assert (AD' : addressable m' v NEWSZ_SSVC) by (xp_addr XP AD IN FXS). clear AD FXS.
    unfold NEWSZ_SSVC in *. split; [exact IN|]. split; [xp_keep XP XR|]. split; [exact E1|]. split; [exact E2|]. split; [exact RB| exact AD'].
  Qed.

