  Lemma AImplBlock_xpres : forall LB SP X m m' b I,
    AImplBlock LB m b I -> xpres H LB SP X m m' ->
    Forall (fun iv : Z * Z => b + SZ_SPCI_IMPL <= fst iv \/ snd iv <= b) X ->
    Forall (fun iv : Z * Z => sh b + nsh SZ_SPCI_IMPL <= fst iv \/ snd iv <= sh b) X ->
    (0 < im_vcap I -> Forall (fun iv : Z * Z => im_vb I + 8 * im_vcap I <= fst iv \/ snd iv <= im_vb I) X) ->
    (0 < im_vcap I -> Forall (fun iv : Z * Z => sh (im_vb I) + nsh (8 * im_vcap I) <= fst iv \/ snd iv <= sh (im_vb I)) X) ->
    AImplBlock LB m' b I.
