  Lemma AStateBlock_xpres : forall LB SP X m m' b ioc implb S ds,
    AStateBlock LB m b ioc implb S ds -> xpres H LB SP X m m' ->
    Forall (fun iv : Z * Z => b + SZ_SPCI_STATE <= fst iv \/ snd iv <= b) X ->
    Forall (fun iv : Z * Z => sh b + nsh SZ_SPCI_STATE <= fst iv \/ snd iv <= sh b) X ->
    (st_fb S <> FB_empty -> Forall (fun iv : Z * Z => fb_end (st_fb S) <= fst iv \/ snd iv <= fb_begin (st_fb S)) X) ->
    (st_fb S <> FB_empty -> Forall (fun iv : Z * Z => sh (fb_begin (st_fb S)) + nsh (fb_cap (st_fb S)) <= fst iv \/ snd iv <= sh (fb_begin (st_fb S))) X) ->
